exercices.solution:
#include <stdlib.h>

typedef struct Maillon {
    int val;
    struct Maillon *suiv;
} Maillon;

int taille(Maillon *l) {
    int n = 0;
    for (Maillon *p = l; p != NULL; p = p->suiv)
        n++;
    return n;
}

