exercices.solution:
#include <stdlib.h>

typedef struct Maillon {
    int val;
    struct Maillon *suiv;
} Maillon;

Maillon *inverser(Maillon *l) {
    Maillon *precedent = NULL;
    Maillon *courant = l;
    while (courant != NULL) {
        Maillon *suivant = courant->suiv;
        courant->suiv = precedent;
        precedent = courant;
        courant = suivant;
    }
    return precedent;
}
